SELECT  FROM data_operation
WHERE status='SUCCEEDED' AND operation_type='EXPORT' AND artifact_expires_at <= #{now}
ORDER BY artifact_expires_at ASC, id ASC LIMIT #{limit}

SELECT  FROM data_operation
WHERE status IN ('PENDING','RUNNING') AND updated_at <= #{cutoff}
ORDER BY updated_at ASC, id ASC LIMIT #{limit}
